import re




def extract_files(data):
    # Pattern for common document types
    file_pattern = r'https?://[^\s<>"]+\.(?:pdf|docx|odt|xlsx|zip|csv)'
    found_urls = set()

    #  Check structured keys
    schedules = data.get('framework_schedules', [])
    for item in schedules:
        if isinstance(item, dict):
            url = item.get('framework_schedule_document')
            if url:
                found_urls.add(url)

    # 2. Recursive deep scan for everything else (HTML, strings)
    def search_recursively(obj):
        if isinstance(obj, str):
            matches = re.findall(file_pattern, obj)
            for match in matches:
                found_urls.add(match)
        elif isinstance(obj, dict):
            for val in obj.values():
                search_recursively(val)
        elif isinstance(obj, list):
            for item in obj:
                search_recursively(item)

    search_recursively(data)

    # Return list of dicts for rm_page_data.py
    return [{"url": url} for url in found_urls]


